function drawParticles(front){
  var n = 0;
  ctx.save();
  for (var i=0;i<MAX;i++){
    var p = P[i];
    if (!p.on || p.front !== front || p.kind === K_EMBER) continue;
    var u = p.t/p.life;
    // fade in fast, fade out long
    var a = p.a0 * smooth(u/0.14) * (1 - smoother(clamp((u-0.16)/0.84,0,1)));
    if (a <= 0.004) continue;
    if (p.x < -p.r*1.4 || p.x > W+p.r*1.4 || p.y > H+p.r*1.4 || p.y < -p.r*1.6) continue;
    ctx.globalAlpha = a;
    ctx.setTransform(DPR,0,0,DPR,0,0);
    ctx.translate(p.x, p.y); ctx.rotate(p.rot);
    var d = p.r*2;
    ctx.drawImage(p.spr, -p.r, -p.r, d, d);
    n++;
  }
  ctx.restore();
  ctx.setTransform(DPR,0,0,DPR,0,0);
  return n;
}

