input.old_string:
/* heat haze: re-sample the frame in wavy horizontal strips */
function heatHaze(cx, cy, hw2, hh, amp, t){
  if (amp < 0.4) return;
  ctx.save();
  ctx.setTransform(1,0,0,1,0,0);
  var x = Math.max(0, (cx-hw2)*DPR), w = Math.min(CV.width-x, hw2*2*DPR);
  var y = Math.max(0, cy*DPR), h = Math.min(CV.height-y, hh*DPR);
  if (w<=1 || h<=1){ ctx.restore(); ctx.setTransform(DPR,0,0,DPR,0,0); return; }
  var strips = 14, sh = h/strips;
  ctx.globalAlpha = 0.9;
  for (var i=0;i<strips;i++){
    var sy = y + i*sh;
    var f = 1 - i/strips;
    var off = Math.sin(t*9 + i*0.85)*amp*DPR*f + Math.sin(t*15.7 + i*1.9)*amp*0.4*DPR*f;
    ctx.drawImage(CV, x, sy, w, sh, x+off, sy, w, sh);
  }
  ctx.restore();
  ctx.setTransform(DPR,0,0,DPR,0,0);
}

