  ctx.save();
  ctx.lineCap = 'round';
  for (var f=0; f<3; f++){
    ctx.globalAlpha = 0.30 - f*0.08;
    ctx.strokeStyle = '#eaf7ff';
    ctx.lineWidth = (2.6 - f*0.7) * (H/900);
