var SPRITES = [];
var SHADES = [
  [255,252,246],   // 0 flash-lit core
  [216,220,224],   // 1 light gray
  [162,168,175],   // 2 mid gray
  [112,118,125],   // 3 cool shadow
  [255,206,158]    // 4 warm, freshly burnt
];

function buildSprites(){
  SPRITES.length = 0;
  var S = 128;
  for (var s=0; s<SHADES.length; s++){
    var col = SHADES[s], group = [];
    for (var v=0; v<6; v++){
      var oc = document.createElement('canvas');
      oc.width = oc.height = S;
      var g = oc.getContext('2d');
      var blobs = 8 + (v%4);
      for (var b=0; b<blobs; b++){
        // lobes are scattered off-centre so the silhouette never reads as a disc,
        // but stay inside the sprite so no hard edge is ever visible
        var a  = rnd()*6.283, d = Math.pow(rnd(),0.6)*S*0.21;
        var cx = S/2 + Math.cos(a)*d, cy = S/2 + Math.sin(a)*d*0.85;
        var rr = S*(0.10 + rnd()*0.15);
        var gr = g.createRadialGradient(cx,cy,0,cx,cy,rr);
        gr.addColorStop(0,   'rgba('+col[0]+','+col[1]+','+col[2]+',0.24)');
        gr.addColorStop(0.32,'rgba('+col[0]+','+col[1]+','+col[2]+',0.15)');
        gr.addColorStop(0.66,'rgba('+col[0]+','+col[1]+','+col[2]+',0.05)');
        gr.addColorStop(1,   'rgba('+col[0]+','+col[1]+','+col[2]+',0)');
        g.fillStyle = gr;
        g.beginPath(); g.arc(cx,cy,rr,0,6.283); g.fill();
      }
      group.push(oc);
    }
    SPRITES.push(group);
  }
}

