/* ───────────────────────── spawning logic ───────────────────────── */
var spawnAcc = { ground:0, mush:0, trail:0, ember:0, ripple:0 };

function emit(t, dt, rocketY, prevY, thr){
  var R = L.R, x = L.rocketX;
  var exY = rocketY + R*0.05, exPrevY = prevY + R*0.05;

  // ── pre-launch steam / water deluge (0.70 → 1.5) ──
  if (t > 0.70 && t < T_LIFT){
    spawnAcc.ground += dt*95;
    while (spawnAcc.ground >= 1){
      spawnAcc.ground -= 1;
      var side = rnd()<0.5?-1:1;
      var s0 = R*(0.018 + rnd()*0.024);
      spawnSmoke(
        x + side*(R*0.03 + Math.pow(rnd(),1.6)*R*0.14),
        L.padY + R*0.015 + rnd()*R*0.03,
        side*(20 + rnd()*66), -(5 + rnd()*20),
        s0, s0*(2.2 + rnd()*1.3),
        2.0 + rnd()*1.6,
        rnd()<0.45 ? 1 : (rnd()<0.6 ? 0 : 2),
        rnd()<0.55?1:0,
        0.13 + rnd()*0.13
      );
    }
  }

  // ── ignition sparks ──
  if (t > T_IGNITE && t < T_LIFT + 0.6){
    spawnAcc.ember += dt*90;
    while (spawnAcc.ember >= 1){
      spawnAcc.ember -= 1;
      var a = (rnd()-0.5)*2.6;
      spawnEmber(x + (rnd()-0.5)*R*0.10, L.padY + R*0.05,
                 Math.sin(a)*(60+rnd()*230), -Math.abs(Math.cos(a))*(20+rnd()*90) + 40);
    }
  }

  if (t >= T_LIFT && t < T_EXIT){
    var u = (t - T_LIFT)/(T_EXIT - T_LIFT);
    var alt = L.padY - rocketY;

    // ── ground cloud keeps boiling outward across the island and water ──
    if (t < T_LIFT + 3.6){
      var groundRate = 125 * (1 - u*0.42);
      spawnAcc.ground += dt*groundRate;
      while (spawnAcc.ground >= 1){
        spawnAcc.ground -= 1;
        var sd = rnd()<0.5?-1:1;
        var spread = Math.min(1, alt/(H*0.22));
        var near = Math.pow(rnd(), 1.7);         // dense at the pad, thinning outward
        var g0 = R*(0.022 + rnd()*0.028);
        spawnSmoke(
          x + sd*(R*0.03 + near*R*0.30*(0.3+spread)),
          L.padY + R*0.015 + rnd()*R*0.045,
          sd*(40 + near*rnd()*165*(0.4+spread)), -(3 + rnd()*26),
          g0, g0*(2.3 + rnd()*1.5),
          2.6 + rnd()*1.8,
          near < 0.20 ? (rnd()<0.40?0:4) : (rnd()<0.45 ? 1 : (rnd()<0.68?2:3)),
          rnd()<0.62?1:0,
          0.12 + rnd()*0.14
        );
      }
      // mushroom roll-up right at the pad
      spawnAcc.mush += dt*42;
      while (spawnAcc.mush >= 1){
        spawnAcc.mush -= 1;
        var m0 = R*(0.026 + rnd()*0.030);
        spawnSmoke(x + (rnd()-0.5)*R*0.18, L.padY - R*0.02 - rnd()*R*0.09,
          (rnd()-0.5)*55, -(20 + rnd()*48),
          m0, m0*(2.1 + rnd()*1.3),
          2.4 + rnd()*1.8,
          rnd()<0.4?1:(rnd()<0.62?0:2), rnd()<0.5?1:0,
          0.12 + rnd()*0.12);
      }
    }

    // ── the column of smoke trailing the vehicle ──
    // spawns are spread along the path flown this frame so the trail never gaps
    var trailRate = 105;
    spawnAcc.trail += dt*trailRate;
    while (spawnAcc.trail >= 1){
      spawnAcc.trail -= 1;
      var back = rnd();
      var sy = lerp(exY, exPrevY, back);
      var thin = clamp(1 - alt/(H*1.05), 0.20, 1);   // trail thins with altitude
      var t0 = R*(0.016 + rnd()*0.024)*(0.45 + 0.55*thin);
      var fresh = rnd() < 0.32;                      // still glowing from the plume
      spawnSmoke(
        x + (rnd()-0.5)*R*0.15*thin,
        sy + rnd()*R*0.05,
        (rnd()-0.5)*(60 + 80*(1-thin)),
        (8 + rnd()*60),
        t0, t0*(2.0 + rnd()*1.4),
        2.2 + rnd()*1.8,
        fresh ? (rnd()<0.5?4:0) : (rnd()<0.42 ? 1 : (rnd()<0.65?2:3)),
        rnd()<0.35?1:0,
        (0.11 + rnd()*0.13) * (0.55 + 0.45*thin)
      );
    }

    // ── embers off the plume ──
    spawnAcc.ember += dt*(70*(1-u*0.6));
    while (spawnAcc.ember >= 1){
      spawnAcc.ember -= 1;
      var a2 = (rnd()-0.5)*2.2;
      spawnEmber(x + (rnd()-0.5)*R*0.07, lerp(exY, exPrevY, rnd()) + R*0.05,
                 Math.sin(a2)*(50+rnd()*260), 40 + rnd()*220);
    }

